import React from "react";
import { useNavigate } from "react-router-dom";
import { AiFillStar } from "react-icons/ai";
import { FiMapPin } from "react-icons/fi";
import { FaRegHeart } from "react-icons/fa";
import { IconType } from "react-icons";

interface SalonCardProps {
  id: string;
  image: string;
  name: string;
  distance: string;
  location: string;
  rating: number;
  reviews: number;
  services?: string[]; // Added optional services prop
}

const SalonCard: React.FC<SalonCardProps> = ({
  id,
  image,
  name,
  distance,
  location,
  rating,
  reviews,
}) => {
  const navigate = useNavigate();
  
  // Create components from icons
  const HeartIcon = FaRegHeart as IconType;
  const MapIcon = FiMapPin as IconType;
  const StarIcon = AiFillStar as IconType;

  return (
    <div
      onClick={() => navigate(`/salon/${id}`)}
      style={{
        width: "280px",
        height: "211px",
        backgroundColor: "#fff",
        borderRadius: "10px",
        boxShadow: "0 4px 10px rgba(0,0,0,0.12)",
        cursor: "pointer",
        overflow: "hidden",
      }}
    >
      <div style={{ position: "relative" }}>
        <img
          src={image}
          alt={name}
          style={{
            width: "100%",
            height: "120px",
            objectFit: "cover",
          }}
        />
        <div
          style={{
            position: "absolute",
            top: "8px",
            right: "8px",
            background: "rgba(255,255,255,0.8)",
            borderRadius: "50%",
            padding: "6px",
          }}
        >
          <HeartIcon color="#76949F" size={16} />
        </div>
      </div>

      <div style={{ padding: "8px 12px" }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            fontWeight: 600,
            fontSize: "15px",
          }}
        >
          <span>{name}</span>
          <span style={{ color: "#7A7A7A", fontSize: "13px" }}>{distance}</span>
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            marginTop: "3px",
            color: "#7A7A7A",
            fontSize: "13px",
          }}
        >
          <MapIcon size={14} style={{ marginRight: "4px" }} />
          {location}
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            marginTop: "4px",
            fontSize: "13px",
            fontWeight: 500,
          }}
        >
          <StarIcon color="#FFD03F" size={16} style={{ marginRight: "4px" }} />
          <span>{rating}</span>
          <span style={{ color: "#7A7A7A", marginLeft: "4px" }}>({reviews})</span>
        </div>
      </div>
    </div>
  );
};

export default SalonCard;
